<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import AccessDialog from './AccessDialog.vue'
import TableViewport from './TableViewport.vue'
import ListPagination from './ListPagination.vue'
import SingleFileUpload from './SingleFileUpload.vue'
import {vSingleSelect} from '@/directives/singleSelect'
import {confirmAction} from '@/state/uiConfirmation'
import {forwardersApi,carrierNames,type ForwarderDocument,type ForwarderInput,type ForwarderOptions} from '@/api/forwarders'
import {customsApi,type CustomsRow} from '@/api/customs'
import {customsWarehousesApi} from '@/api/customsDocuments'
import {domainApi} from '@/api/domain'
import {catalogApi} from '@/api/catalog'
import {orderFields,recipientFields,shipperFields,importerFields,itemFields,blankForwarderItem,forwarderTotals,pictureSnapshot} from '@/ui/forwarderFields'
const props=defineProps<{document?:ForwarderDocument|undefined;writable:boolean;exportable:boolean}>(),emit=defineEmits<{close:[];saved:[ForwarderDocument]}>()
const form=ref<ForwarderInput>(props.document?JSON.parse(JSON.stringify(props.document)):{documentNo:'',carrier:'KAIQI',status:'DRAFT',fields:{country:'US',insured:'否',battery:'不带电',magnet:'不带磁',extraService:'否'},items:[]}),id=ref(props.document?.id),baseline=ref(JSON.stringify(form.value)),busy=ref(false),error=ref(''),notice=ref(''),tab=ref('shipment'),options=ref<ForwarderOptions>({channels:[],addresses:[],templateVersion:'v1'}),optionsError=ref(''),optionsLoading=ref(false)
const dialog=ref<InstanceType<typeof AccessDialog>>(),dirty=computed(()=>baseline.value!==JSON.stringify(form.value)),totals=computed(()=>forwarderTotals(form.value.items)),row=ref<Record<string,string>>(),rowIndex=ref(-1),rowBaseline=ref(''),rowDialog=ref<InstanceType<typeof AccessDialog>>()
const picker=ref(false),query=ref(''),applied=ref(''),page=ref(1),size=ref(20),skuRows=ref<CustomsRow[]>([]),skuTotal=ref(0),selected=ref<CustomsRow[]>([]),picking=ref(false),pickerError=ref('');let request=0,lookup=0
const headerGroups=computed(()=>tab.value==='importer'?[{title:'进口商信息（按货代要求填写）',fields:importerFields}]:[{title:'运单信息',fields:orderFields.filter(([k])=>form.value.carrier==='KAIQI'||['waybill','reference','warehouse','country'].includes(k))},{title:'收件人信息',fields:recipientFields.filter(([k])=>form.value.carrier==='HUAMAO'||!['consigneeVat','consigneeEori'].includes(k))},...(form.value.carrier==='HUAMAO'?[{title:'发件人信息',fields:shipperFields}]:[])])
const choices:Record<string,string[]>={customsType:['退税报关','买单报关'],insured:['否','是'],battery:['不带电','带电'],magnet:['不带磁','带磁'],extraService:['否','是']}
async function loadOptions(){const carrier=form.value.carrier;optionsLoading.value=true;optionsError.value='';try{const result=await forwardersApi.options(carrier);if(form.value.carrier===carrier)options.value=result}catch(e){optionsError.value=String(e instanceof Error?e.message:e)}finally{optionsLoading.value=false}}
watch(()=>form.value.carrier,()=>{tab.value='shipment';void loadOptions()})
async function matchAddress(){const code=(form.value.fields.warehouse??'').trim().toUpperCase();form.value.fields.warehouse=code;const seq=++lookup;if(!code||!props.writable)return;busy.value=true;error.value='';try{const official=(await customsWarehousesApi.list()).find(r=>r.code===code),reference=options.value.addresses.find(r=>r.code?.toUpperCase()===code);if(seq!==lookup)return;if(!official&&!reference){notice.value='未匹配仓库，请填写本票收件地址';return}let address=official?.address??reference?.address??'';if(official){const suffix=`, ${official.city}, ${official.region} ${official.postalCode}, United States`;if(address.endsWith(suffix))address=address.slice(0,-suffix.length)}if(form.value.fields.address&&form.value.fields.address!==address&&!await confirmAction('本票已填写收件地址，是否按仓库资料替换收件信息？'))return;if(seq!==lookup)return;Object.assign(form.value.fields,{address,city:official?.city??reference?.city??'',region:official?.region??reference?.region??'',postalCode:official?.postalCode??reference?.postalCode??'',consignee:reference?.consignee||code,company:reference?.company||'Amazon.com Services.Inc',phone:reference?.phone??'',address2:reference?.address2??''});notice.value='已带入仓库地址，请核对本票收件信息'}catch(e){error.value=e instanceof Error?e.message:'地址匹配失败，可重试或手动填写'}finally{busy.value=false}}
function editItem(index:number){rowIndex.value=index;row.value=index<0?{...blankForwarderItem(),boxStart:String(Math.max(0,...form.value.items.map(r=>Number(r.boxStart||1)+Number(r.boxCount||0)-1))+1),boxCount:'1',fba:'',reference:form.value.fields.reference??''}:{...form.value.items[index]!};rowBaseline.value=JSON.stringify(row.value)}
function applyItem(){if(!row.value)return;if(rowIndex.value<0)form.value.items.push({...row.value});else form.value.items[rowIndex.value]={...row.value};row.value=undefined}
async function removeItem(i:number){if(await confirmAction('移除此项装箱商品？'))form.value.items.splice(i,1)}
async function photo(file:File){if(!row.value)return;busy.value=true;try{row.value.image=await pictureSnapshot(file)}catch(e){error.value=e instanceof Error?e.message:'图片处理失败';throw e}finally{busy.value=false}}
async function loadSkus(){const seq=++request;picking.value=true;pickerError.value='';try{const result=await customsApi.list(applied.value,'',page.value-1,size.value);if(seq===request){skuRows.value=result.items;skuTotal.value=result.totalCount}}catch(e){pickerError.value=e instanceof Error?e.message:'SKU加载失败'}finally{if(seq===request)picking.value=false}}
watch([page,size],()=>{if(picker.value)void loadSkus()})
async function openPicker(){selected.value=[];picker.value=true;await loadSkus()}
function toggle(r:CustomsRow){selected.value=selected.value.some(v=>v.variantId===r.variantId)?selected.value.filter(v=>v.variantId!==r.variantId):[...selected.value,r]}
async function addSelected(){picking.value=true;pickerError.value='';try{if(form.value.items.length+selected.value.length>100)throw new Error('每票最多100项商品');for(const sku of selected.value){const c=sku.customs,item:Record<string,string>={...blankForwarderItem(),sku:sku.skuCode,variantId:sku.variantId,name:c?.nameZh??sku.skuName,nameEn:c?.nameEn??'',hsCode:c?.usCode??'',brand:c?.elements?.brand||c?.brand||'',brandType:c?.elements?.brandType??'',model:c?.elements?.articleNumber||c?.elements?.dimensions||c?.model||'',material:c?.elements?.compositionContent||c?.elements?.fiberComposition||c?.composition||'',usage:c?.usage??'',fba:'',reference:form.value.fields.reference??'',boxStart:String(Math.max(0,...form.value.items.map(r=>Number(r.boxStart||1)+Number(r.boxCount||0)-1))+1),boxCount:'1'};try{const product=await domainApi.product(sku.productId),variant=product.variants.find(v=>v.id===sku.variantId);if(variant?.imageAssetId)item.image=await pictureSnapshot(await catalogApi.imageBlob(variant.imageAssetId));else if(variant?.imageUrl){const response=await fetch(variant.imageUrl,{credentials:'omit',referrerPolicy:'no-referrer'});if(response.ok)item.image=await pictureSnapshot(await response.blob())}}catch{notice.value='部分产品图片未能带入，请在商品资料中上传'}form.value.items.push(item)}picker.value=false;tab.value='items'}catch(e){pickerError.value=e instanceof Error?e.message:'添加失败'}finally{picking.value=false}}
async function save(){if(busy.value||!props.writable)return;busy.value=true;error.value='';try{const result=await forwardersApi.save(form.value,id.value);form.value=JSON.parse(JSON.stringify(result));id.value=result.id;baseline.value=JSON.stringify(form.value);notice.value='单据已保存';emit('saved',result)}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function exportFile(){if(!id.value||dirty.value)return;busy.value=true;error.value='';try{await forwardersApi.export({id:id.value,carrier:form.value.carrier,documentNo:form.value.documentNo})}catch(e){error.value=e instanceof Error?e.message:'导出失败'}finally{busy.value=false}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{void loadOptions();window.addEventListener('beforeunload',beforeUnload)});onBeforeUnmount(()=>{++lookup;++request;window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
  <!-- eslint-disable vue/max-attributes-per-line, vue/singleline-html-element-content-newline -->
  <AccessDialog ref="dialog" :title="id?'货代单据详情':'新建货代单据'" wide dialog-class="forwarder-editor" :dirty="dirty" :busy="busy||picking" @close="emit('close')">
    <div class="forwarder-summary"><span>{{ carrierNames[form.carrier] }} · {{ options.templateVersion }} 模板</span><strong>{{ totals.boxes }} 箱</strong><span>{{ form.items.length }} 项商品 · {{ totals.quantity }} 件</span><strong>USD {{ totals.amount }}</strong></div>
    <nav class="ui-section-tabs"><button v-for="[key,label] in [['shipment','运单与收件信息'],['items','商品与装箱'],...(form.carrier==='HUAMAO'?[['importer','进口商']]:[])]" :key="key" type="button" :aria-pressed="tab===key" :class="{active:tab===key}" @click="tab=key!">{{ label }}</button></nav>
    <p v-if="error" class="data-state--error" role="alert">{{ error }}</p><p v-if="notice" class="forwarder-notice" role="status">{{ notice }}</p><p v-if="optionsError" role="alert">{{ optionsError }} <button @click="loadOptions">重新加载模板</button></p>
    <fieldset :disabled="busy||!writable" class="forwarder-fields">
      <div v-if="tab==='shipment'" class="forwarder-grid"><label>合作货代<select v-model="form.carrier" v-single-select :disabled="!!id||optionsLoading" aria-label="合作货代"><option value="KAIQI">凯琦</option><option value="HUAMAO">华茂万通</option></select></label><label>单据编号<input v-model="form.documentNo" placeholder="保存时自动生成" maxlength="128"></label><label>资料状态<select v-model="form.status" v-single-select><option value="DRAFT">草稿</option><option value="READY">资料已核对</option></select></label></div>
      <template v-if="tab!=='items'"><section v-for="group in headerGroups" :key="group.title"><h3>{{ group.title }}</h3><div class="forwarder-grid"><label v-for="[key,label,type] in group.fields" :key="key" :class="{wide:['address','shipperAddress','importerAddress','notes'].includes(key)}">{{ label }}<select v-if="choices[key]" v-model="form.fields[key]" v-single-select :aria-label="label"><option value="">请选择</option><option v-for="v in choices[key]" :key="v" :value="v">{{ v }}</option></select><template v-else-if="key==='channel'"><input v-model="form.fields[key]" list="forwarder-channels" :aria-label="label" placeholder="选择模板渠道或输入"><datalist id="forwarder-channels"><option v-for="v in options.channels" :key="v" :value="v" /></datalist></template><textarea v-else-if="['address','shipperAddress','importerAddress','notes'].includes(key)" v-model="form.fields[key]" rows="2" maxlength="2000" :aria-label="label" /><input v-else v-model="form.fields[key]" :type="type==='number'?'number':'text'" :readonly="key==='country'" :min="type==='number'?0:undefined" step="0.01" maxlength="2000" :aria-label="label" @blur="key==='warehouse'&&matchAddress()"><button v-if="key==='warehouse'" type="button" class="text-action" @click="matchAddress">匹配地址</button></label></div></section></template>
    </fieldset>
    <template v-if="tab==='items'"><div class="forwarder-toolbar"><button v-if="writable" class="ui-button-primary" :disabled="busy||form.items.length>=100" @click="openPicker">选择产品 SKU</button><button v-if="writable" :disabled="busy||form.items.length>=100" @click="editItem(-1)">手动添加商品</button><span>同箱混装共用箱序范围，箱数只统计一次；填写实际毛重，非体积重。</span></div><TableViewport><table class="data-table forwarder-items"><thead><tr><th>图片</th><th>商品 / SKU</th><th>起始箱序</th><th>箱数</th><th>单箱数量</th><th>单价 USD</th><th>实际毛重 kg/箱</th><th>箱规 cm</th><th>操作</th></tr></thead><tbody><tr v-for="(r,i) in form.items" :key="i"><td><img v-if="r.image" :src="r.image" alt="产品图片"><span v-else>待补充</span></td><td>{{ r.name||'待填写品名' }}<small>{{ r.sku||'手工商品' }}</small></td><td v-for="key in ['boxStart','boxCount','perBox','price','grossWeight']" :key="key"><input v-model="r[key]" type="number" min="0" :step="['price','grossWeight'].includes(key)?'0.0001':'1'" :disabled="busy||!writable" :aria-label="`商品${i+1} ${key}`"></td><td>{{ [r.length,r.width,r.height].filter(Boolean).join(' × ')||'待填写' }}</td><td><button class="text-action" :disabled="busy" @click="editItem(i)">{{ writable?'编辑资料':'查看资料' }}</button><button v-if="writable" class="text-action danger" :disabled="busy" @click="removeItem(i)">移除</button></td></tr><tr v-if="!form.items.length"><td colspan="9" class="data-state">选择 SKU 带入报关资料和图片，再补充本票装箱数量、箱规及价格。</td></tr></tbody></table></TableViewport></template>
    <template #footer><span>{{ dirty?'有未保存修改':id?'已保存资料可导出':'填写后保存，即可导出' }}</span><div><button @click="dialog?.requestClose()">关闭</button><button v-if="exportable" :disabled="busy||dirty||!id" @click="exportFile">导出{{ carrierNames[form.carrier] }}模板</button><button v-if="writable" class="ui-button-primary candidate-primary" :disabled="busy||optionsLoading" @click="save">{{ busy?'处理中…':'保存单据' }}</button></div></template>
  </AccessDialog>
  <AccessDialog v-if="row" ref="rowDialog" :title="writable?'商品及装箱资料':'商品资料'" wide :dirty="JSON.stringify(row)!==rowBaseline" :busy="busy" @close="row=undefined"><fieldset :disabled="busy||!writable" class="forwarder-fields"><div class="forwarder-photo"><img v-if="row.image" :src="row.image" alt="当前产品图片"><SingleFileUpload v-if="writable" title="产品图片" accept=".png,.jpg,.jpeg,.webp" :max-mb="5" :upload="photo" :disabled="busy" deferred hint="支持选择、拖拽或粘贴图片，随单据保存" /></div><div class="forwarder-grid"><label v-for="[key,label,type] in itemFields.filter(([k])=>form.carrier==='KAIQI'||!['brandType','boxCode'].includes(k))" :key="key">{{ label }}<input v-model="row[key]" :type="type==='number'?'number':'text'" min="0" step="0.0001" maxlength="2000" :aria-label="label"></label></div></fieldset><template #footer><button @click="rowDialog?.requestClose()">取消</button><button v-if="writable" class="ui-button-primary" :disabled="busy" @click="applyItem">确定</button></template></AccessDialog>
  <AccessDialog v-if="picker" title="选择产品 SKU" wide :busy="picking" @close="picker=false"><form class="forwarder-toolbar" @submit.prevent="applied=query;page=1;loadSkus()"><input v-model="query" aria-label="搜索产品 SKU" placeholder="搜索 SKU / 品名"><button class="ui-button-primary" :disabled="picking">搜索</button><span>已选 {{ selected.length }} 项</span></form><p v-if="pickerError" role="alert">{{ pickerError }}</p><TableViewport><table class="data-table"><thead><tr><th>选择</th><th>SKU</th><th>品名</th><th>英文品名</th><th>美国 HS</th></tr></thead><tbody><tr v-for="r in skuRows" :key="r.variantId"><td><input type="checkbox" :checked="selected.some(s=>s.variantId===r.variantId)" :disabled="picking" :aria-label="`选择 ${r.skuCode}`" @change="toggle(r)"></td><td>{{ r.skuCode }}</td><td>{{ r.customs?.nameZh||r.skuName }}</td><td>{{ r.customs?.nameEn||'未维护' }}</td><td>{{ r.customs?.usCode||'未维护' }}</td></tr><tr v-if="!skuRows.length"><td colspan="5">{{ picking?'加载中…':'暂无匹配 SKU' }}</td></tr></tbody></table></TableViewport><ListPagination v-model:page="page" v-model:page-size="size" :total="skuTotal" :disabled="picking" /><template #footer><button :disabled="picking" @click="picker=false">取消</button><button class="ui-button-primary" :disabled="picking||!selected.length" @click="addSelected">{{ picking?'正在带入资料…':`添加所选（${selected.length}）` }}</button></template></AccessDialog>
</template>
<style>
.forwarder-editor{width:min(1240px,calc(100vw - 24px))}.forwarder-summary{display:flex;gap:20px;align-items:center;padding:8px 0 14px;font-size:13px;color:var(--muted)}.forwarder-summary strong{font-size:17px;color:var(--ink)}.forwarder-fields{border:0;padding:0;margin:0;min-width:0}.forwarder-fields h3{font-size:14px;margin:16px 0 10px;border-left:3px solid #2879db;padding-left:8px}.forwarder-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 16px}.forwarder-grid label{display:flex;flex-direction:column;gap:6px;font-size:13px;min-width:0}.forwarder-grid input,.forwarder-grid textarea,.forwarder-grid select{box-sizing:border-box;width:100%;min-height:40px;border:1px solid var(--line);border-radius:4px;padding:8px;font-size:13px}.forwarder-grid label:has(>button){position:relative}.forwarder-grid label:has(>button)>input{padding-right:94px}.forwarder-grid label>button.text-action{position:absolute;right:5px;bottom:6px;min-height:28px;width:auto}.forwarder-editor footer>span{margin-right:auto;font-size:12px;color:var(--muted)}.forwarder-grid .wide{grid-column:span 3}.forwarder-toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0;font-size:12px;color:var(--muted)}.forwarder-toolbar input{height:32px;border:1px solid var(--line);border-radius:4px;padding:0 10px;min-width:230px}.forwarder-items{min-width:1100px}.forwarder-items input{width:90px}.forwarder-items img{width:55px;height:55px;object-fit:contain}.forwarder-items small{display:block;color:var(--muted)}.forwarder-items td:last-child{position:sticky;right:0;background:white;white-space:nowrap}.forwarder-items th:last-child{position:sticky;right:0;z-index:3}.forwarder-photo{display:flex;gap:16px;align-items:center;margin:12px 0}.forwarder-photo>img{width:120px;height:120px;object-fit:contain}.forwarder-notice{font-size:12px;color:#24714b}.forwarder-editor footer>div{display:flex;gap:8px;flex-wrap:wrap}.forwarder-editor .text-action{border:0;background:none;color:#2864c5;padding:4px 6px;min-height:28px}.forwarder-editor .danger{color:#b42318}@media(max-width:700px){.forwarder-photo{flex-direction:column;align-items:stretch}.forwarder-photo>img{align-self:center}.forwarder-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.forwarder-grid .wide{grid-column:span 2}.forwarder-summary{gap:10px;flex-wrap:wrap}}@media(max-width:450px){.forwarder-grid{grid-template-columns:1fr}.forwarder-grid .wide{grid-column:span 1}}
</style>
